import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import axios from 'axios';
import Navbar from './components/Navbar';
import Home from './pages/Home';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import ProductForm from './pages/ProductForm';
import Sell from './pages/Sell';

// Configure axios defaults - connect to backend on port 5000
axios.defaults.baseURL = 'http://localhost:5000';
axios.defaults.headers.common['Content-Type'] = 'application/json';
axios.defaults.withCredentials = true;

// Request Interceptor - Add auth token to all requests and log requests
axios.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  console.log('📤 API Request:', config.method.toUpperCase(), config.url);
  return config;
}, (error) => {
  console.error('❌ Request Error:', error);
  return Promise.reject(error);
});

// Response Interceptor - Handle auth errors and log responses
axios.interceptors.response.use(
  (response) => {
    console.log('📥 API Response:', response.status, response.config.url);
    return response;
  },
  (error) => {
    console.error('❌ Response Error:', error.response?.status, error.message);
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
    }
    return Promise.reject(error);
  }
);

// Backend Status Component - Demonstrates frontend-backend connection
function BackendStatus() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchBackendStatus = async () => {
      try {
        setLoading(true);
        setError(null);
        console.log('🔌 Attempting to connect to backend at http://localhost:5001/');
        const response = await axios.get('/');
        setData(response.data);
        console.log('✅ Backend connection successful:', response.data);
      } catch (err) {
        console.error('❌ Error fetching backend:', err);
        setError(err.message || 'Failed to connect to backend');
      } finally {
        setLoading(false);
      }
    };

    fetchBackendStatus();
  }, []);

  return (
    <div className="backend-status" style={{
      padding: '15px',
      margin: '10px 0',
      borderRadius: '5px',
      backgroundColor: loading ? '#fff3cd' : error ? '#f8d7da' : '#d4edda',
      border: `1px solid ${loading ? '#ffc107' : error ? '#dc3545' : '#28a745'}`,
      fontSize: '14px'
    }}>
      <strong>🔌 Backend Connection Status:</strong>
      {loading && <p>⏳ Loading...</p>}
      {error && <p style={{color: '#dc3545'}}>❌ Network Error: {error}</p>}
      {data && (
        <div>
          <p style={{color: '#28a745'}}>✅ {data.message}</p>
          {data.timestamp && <p>Server Time: {new Date(data.timestamp).toLocaleString()}</p>}
        </div>
      )}
    </div>
  );
}

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      setIsAuthenticated(true);
    }
  }, []);

  return (
    <Router>
      <Navbar isAuthenticated={isAuthenticated} setAuth={setIsAuthenticated} />
      <BackendStatus />
      <div className="app-container">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={isAuthenticated ? <Navigate to="/dashboard" /> : <Login setAuth={setIsAuthenticated} />} />
          <Route path="/register" element={isAuthenticated ? <Navigate to="/dashboard" /> : <Register setAuth={setIsAuthenticated} />} />
          <Route path="/dashboard" element={isAuthenticated ? <Dashboard setAuth={setIsAuthenticated} /> : <Navigate to="/login" />} />
          <Route path="/sell" element={isAuthenticated ? <Sell /> : <Navigate to="/login" />} />
          <Route path="/add-product" element={isAuthenticated ? <ProductForm /> : <Navigate to="/login" />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
